import { p } from "@paradoc/core";
import type { Form } from "@paradoc/types";

import type { DocumentTokensInput } from "@paradoc/react";

/**
 * The invoice form artifact this package's billing document composes.
 *
 * Sample material, like the rest of `./examples`. It is the third priced
 * document here, and it is a different question from the other two. The
 * proposal is an offer and the purchase order is an instruction, so both are
 * signed; an invoice is a demand for money already owed, so nothing signs it.
 * The artifact therefore declares its parties and gives neither a signature,
 * and its React layer carries no signature slot at all. What it proves is that
 * the same components compose a document the seal never touches.
 *
 * Everything the document shows is declared here: the issuer and the customer,
 * the numbering and the dates, the line-item list, the currency and tax inputs
 * behind the computed totals, and the payment terms. The React components read
 * this artifact and never carry their own copy of a label, a format, or a
 * total.
 *
 * The one limitation the other priced samples record applies here too. The
 * expression language indexes lists and reads their length, but it has no
 * aggregate over a list, so a subtotal cannot be expressed as a def.
 * `subtotalAmount` is a field the caller materializes with `computeLineAmounts`,
 * and the artifact computes tax and total from it. See the package README.
 *
 * Like the purchase order, this composition does not wrap itself in a `Bundle`:
 * it renders bare so a caller who puts it inside a packet supplies the bundle.
 */

/** The layer that names the composition. */
export const INVOICE_REACT_LAYER = "composition";

/**
 * The composition module the React layer points at, as the layer declares it.
 *
 * Relative to the artifact file that declares it, which is this one, so it names
 * the sibling module and nothing more. The string is the key a consumer binds
 * the component under, so it is exported rather than written twice.
 */
export const INVOICE_REACT_LAYER_PATH = "invoice-document.tsx";

/**
 * The issuer's mark, as base 64 PNG.
 *
 * Drawn here rather than shipped as a file, exactly as `src/examples/tokens.ts`
 * draws the branded proposal's: `logo` accepts bytes as well as a string, and a
 * sample that only ever passed a string would leave that half unexercised. The
 * token resolves bytes to a `data:` URI, which is the one image source neither
 * the browser nor the engine has to fetch — so the invoice needs no image
 * wiring on either side, and a consumer who installs the block gets a document
 * that draws its own mark.
 */
const INVOICE_LOGO_BASE64 =
  "iVBORw0KGgoAAAANSUhEUgAAACgAAAAoCAYAAACM/rhtAAAArklEQVR42u3YURKAIAgEUG/QTfvs" +
  "+nWDQthdIHXGX3xTDgJj/H0d13m/7ZKoNKwXRoeiYBQoCwdBsnEhpArnQqpxU8gsnBlZGogOCkey" +
  "LjYkLjs1hOMrkqsEqHqZ5F8vdJa6CtnAZYBf8A2UA5FpxnI3UxP1FC7jqaMCo8XC9O9VlltunKJg" +
  "tZ5ZqklP7Uk8Z9E7u8h7XGKClT5dkOFQqaf1hGudAWabEXCbIbpyPWS4915d7BCAAAAAAElFTkSu" +
  "QmCC";

/** Those bytes, decoded once. `atob` rather than `Buffer`: this entry is isomorphic. */
export const invoiceLogo: Uint8Array = Uint8Array.from(atob(INVOICE_LOGO_BASE64), (glyph) =>
  glyph.charCodeAt(0)
);

/** The accent the invoice is drawn in, matching its mark. */
export const INVOICE_ACCENT_COLOR = "#0f766e";

/**
 * The issuer's branding: a mark and an accent, and nothing else.
 *
 * The token set sits beside the artifact for the reason the Arabic letter's
 * does — a sample that was unbranded until a caller passed the right tokens
 * would be a sample nobody could copy — but neither key here is root-only, so
 * the composition hands this to its own `Document` and a caller who layers
 * another set over it changes only what that set names. Paper, margin and
 * typeface stay the package's defaults, which is what keeps the invoice
 * measurable against every other US Letter sample here.
 */
export const invoiceTokens: DocumentTokensInput = {
  accentColor: INVOICE_ACCENT_COLOR,
  logo: invoiceLogo,
};

/** The invoice form, exactly as authored. Kept beside the instance for evaluators that take a raw `Form`. */
export const invoiceSpec = {
  $schema: "https://schema.paradoc.dev/schema.json",
  kind: "form",
  name: "invoice",
  version: "1.0.0",
  title: "Invoice",
  description:
    "A billing document from an issuer to a customer, with line items, computed totals, and payment terms. Nothing signs it.",
  metadata: {
    domain: "commerce",
  },
  parties: {
    issuer: {
      label: "Issuer",
      description: "The organization billing for the work.",
      partyType: "organization",
      min: 1,
      max: 1,
      signature: { required: false, witnesses: 0, notarized: false },
    },
    customer: {
      label: "Bill to",
      description: "The organization the invoice is addressed to.",
      partyType: "organization",
      min: 1,
      max: 1,
      signature: { required: false, witnesses: 0, notarized: false },
    },
  },
  fields: {
    invoiceNumber: {
      type: "text",
      label: "Invoice number",
      description: "Identifier the issuer files this invoice under.",
      maxLength: 40,
      required: true,
      visible: true,
    },
    issuedOn: {
      type: "date",
      label: "Issued",
      description: "Date the issuer raised the invoice.",
      required: true,
      visible: true,
    },
    dueOn: {
      type: "date",
      label: "Due",
      description: "Date payment is due.",
      required: true,
      visible: true,
    },
    issuer: {
      type: "organization",
      label: "Issuer",
      description: "Legal name and identifiers of the billing organization.",
      required: true,
      visible: true,
    },
    issuerAddress: {
      type: "address",
      label: "Issuer address",
      description: "Principal business address of the issuer.",
      required: true,
      visible: true,
    },
    issuerEmail: {
      type: "email",
      label: "Billing email",
      description: "Where the customer writes about this invoice.",
      required: true,
      visible: true,
    },
    customer: {
      type: "organization",
      label: "Bill to",
      description: "The organization the invoice is addressed to.",
      required: true,
      visible: true,
    },
    customerAddress: {
      type: "address",
      label: "Bill to address",
      description: "Billing address of the customer.",
      required: true,
      visible: true,
    },
    customerContact: {
      type: "person",
      label: "Accounts contact",
      description: "The person in the customer's accounts team the invoice is addressed to.",
      required: true,
      visible: true,
    },
    purchaseOrderNumber: {
      type: "text",
      label: "Your order",
      description: "The customer's own order number, quoted so the invoice can be matched to it.",
      maxLength: 40,
      required: false,
      visible: true,
    },
    currency: {
      type: "text",
      label: "Currency",
      description: "ISO 4217 currency code every amount on the invoice is quoted in.",
      pattern: "^[A-Z]{3}$",
      required: true,
      visible: true,
    },
    lineItems: {
      type: "list",
      label: "Line items",
      description: "The billed goods and services, one row per item.",
      minItems: 1,
      required: true,
      visible: true,
      item: {
        type: "fieldset",
        label: "Line item",
        fields: {
          description: {
            type: "text",
            label: "Description",
            maxLength: 300,
            required: true,
            visible: true,
          },
          quantity: {
            type: "number",
            label: "Qty",
            min: 0,
            required: true,
            visible: true,
          },
          unit: {
            type: "text",
            label: "Unit",
            maxLength: 20,
            required: true,
            visible: true,
          },
          unitPrice: {
            type: "money",
            label: "Unit price",
            min: 0,
            required: true,
            visible: true,
          },
          amount: {
            type: "money",
            label: "Amount",
            description:
              "The row multiplied out. Derived rather than answered, like `subtotalAmount` and for the same reason: a filler supplies the quantity and the unit price, and `computeLineAmounts` does the arithmetic.",
            min: 0,
            required: false,
            visible: false,
          },
        },
      },
    },
    subtotalAmount: {
      type: "number",
      label: "Subtotal amount",
      description:
        "Sum of the line-item amounts. Materialized by the caller because the expression language has no list aggregate. Derived rather than answered, so it is invisible and not required: no session asks for it and nothing demands it of a filler.",
      min: 0,
      required: false,
      visible: false,
    },
    taxRatePercent: {
      type: "percentage",
      label: "Tax rate",
      description: "Sales-tax rate applied to the subtotal, as a percentage.",
      min: 0,
      max: 100,
      required: true,
      visible: true,
    },
    paymentTerms: {
      type: "text",
      label: "Payment terms",
      description: "When payment is due and how it is made.",
      maxLength: 2000,
      required: true,
      visible: true,
    },
    notes: {
      type: "text",
      label: "Notes",
      description: "Anything the customer's accounts team needs beyond the terms.",
      maxLength: 2000,
      required: false,
      visible: true,
    },
  },
  defs: {
    subtotal: {
      type: "money",
      label: "Subtotal",
      description: "The line-item total before tax.",
      value: {
        amount: "fields.subtotalAmount",
        currency: "fields.currency",
      },
    },
    tax: {
      type: "money",
      label: "Tax",
      description: "Sales tax on the subtotal at the quoted rate.",
      value: {
        amount: "fields.subtotalAmount * fields.taxRatePercent / 100",
        currency: "fields.currency",
      },
    },
    total: {
      type: "money",
      label: "Amount due",
      description: "What the customer owes.",
      value: {
        amount: "fields.subtotalAmount + fields.subtotalAmount * fields.taxRatePercent / 100",
        currency: "fields.currency",
      },
    },
  },
  defaultLayer: INVOICE_REACT_LAYER,
  layers: {
    [INVOICE_REACT_LAYER]: {
      kind: "file",
      mimeType: "text/tsx",
      path: INVOICE_REACT_LAYER_PATH,
      title: "Composition",
      description:
        "The React composition this invoice is. It declares no signature slot: an invoice is a demand for payment, not an agreement, so there is nothing on it to sign.",
    },
  },
} as const;

/** The parsed, validated invoice form. */
export const invoice = p.form(invoiceSpec);

/**
 * The same validated artifact as a plain `Form`. Everything that renders or
 * evaluates the invoice reads this, so no consumer sees the unparsed spec.
 */
export const invoiceForm: Form = invoice.toJSON() as Form;

import type { RuntimeParty } from "@paradoc/types";

import type { DocumentData } from "@paradoc/react";
import { computeLineAmounts, type LineItemInput } from "@/artifacts/paradoc/line-items";

/**
 * Sample data for the invoice.
 *
 * Two sizes, both measured against the one page of content `Paper` exposes as
 * `PAGE_CONTENT_HEIGHT_PX` (960 pixels: US Letter at 96 dpi less both margins),
 * for the reason the proposal carries two: a document that only ever overflows
 * says nothing about the single-page case, and a document that never overflows
 * says nothing about a break.
 *
 * - `shortInvoiceData` is 5 rows and sits inside one page.
 * - `overflowInvoiceData` is 48 rows and runs past two breaks, so the table's
 *   header is copied onto more than one continued page.
 *
 * The row counts are asserted in `tests/invoice-artifact.test.ts`, so shrinking
 * either set fails rather than quietly breaking the budget.
 */

const CURRENCY = "USD";
const TAX_RATE_PERCENT = 8.25;

const issuer = {
  name: "Northgate Systems",
  legalName: "Northgate Systems, LLC",
  domicile: "US",
  entityType: "Limited liability company",
  taxId: "47-2938471",
};

const customer = {
  name: "Harbor Freight Collective",
  legalName: "Harbor Freight Collective, Inc.",
  domicile: "US",
  entityType: "Corporation",
  taxId: "58-1029384",
};

/** Five rows: one month of delivery work, and it fits one page. */
const SHORT_ITEMS: LineItemInput[] = [
  { description: "Integration architecture, senior engineer", quantity: 6, unit: "day", unitPrice: { amount: 2200, currency: CURRENCY } },
  { description: "Dispatch board build", quantity: 11, unit: "day", unitPrice: { amount: 2050, currency: CURRENCY } },
  { description: "Carrier rate ingestion", quantity: 4, unit: "day", unitPrice: { amount: 2050, currency: CURRENCY } },
  { description: "Release engineering and cutover rehearsal", quantity: 3, unit: "day", unitPrice: { amount: 1900, currency: CURRENCY } },
  { description: "Platform subscription, September", quantity: 1, unit: "month", unitPrice: { amount: 3400, currency: CURRENCY } },
];

/** What the long invoice bills for, one entry per work stream. */
const BILLED_WORK = [
  "Dispatch board build",
  "Route optimization service",
  "Driver check-in flow",
  "Proof-of-delivery capture",
  "Carrier rate ingestion",
  "Invoice export adapter",
  "Telemetry dashboard",
  "Alerting and on-call runbook",
  "Access control review",
  "Load test and tuning",
  "Disaster-recovery rehearsal",
  "Operator training",
  "Cutover rehearsal",
  "Post-launch support",
  "Reference data cleanup",
  "Interface contract review",
  "Reconciliation reporting",
  "Documentation pass",
  "Accessibility remediation",
  "Regional rollout support",
  "Billing reconciliation",
  "Support handover",
  "Environment provisioning",
  "Release pipeline maintenance",
];

/** 48 rows: the table continues across more than one break. */
const OVERFLOW_ITEMS: LineItemInput[] = BILLED_WORK.flatMap((work, index) => [
  {
    description: `${work} — August`,
    quantity: 1 + (index % 5),
    unit: "day",
    unitPrice: { amount: 1850 + (index % 6) * 115, currency: CURRENCY },
  },
  {
    description: `${work} — September`,
    quantity: 2 + (index % 4),
    unit: "day",
    unitPrice: { amount: 1950 + (index % 5) * 105, currency: CURRENCY },
  },
]);

/**
 * The sample's data, whose parties carry runtime ids.
 *
 * A document only prints a party, so `DocumentData` asks for the wider `Party`.
 * Nothing signs an invoice, so no seal reads these ids; they are here because a
 * filled artifact carries them and a sample that dropped them would not be one.
 */
export interface InvoiceData extends DocumentData {
  parties: Record<string, RuntimeParty | RuntimeParty[]>;
}

function build(
  items: LineItemInput[],
  invoiceNumber: string,
  notes: string
): InvoiceData {
  const { lineItems, subtotalAmount } = computeLineAmounts(items, CURRENCY);
  return {
    fields: {
      invoiceNumber,
      issuedOn: "2026-10-01",
      dueOn: "2026-10-31",
      issuer,
      issuerAddress: {
        line1: "1400 Rio Grande Street",
        line2: "Suite 220",
        locality: "Austin",
        region: "TX",
        postalCode: "78701",
        country: "US",
      },
      issuerEmail: "billing@northgate-systems.example",
      customer,
      customerAddress: {
        line1: "88 Wharf Road",
        locality: "Oakland",
        region: "CA",
        postalCode: "94607",
        country: "US",
      },
      customerContact: { name: "Marisol Vega", firstName: "Marisol", lastName: "Vega", title: "Ms." },
      purchaseOrderNumber: "PO-2026-0512",
      currency: CURRENCY,
      lineItems,
      subtotalAmount,
      taxRatePercent: TAX_RATE_PERCENT,
      paymentTerms:
        "Payment is due 30 days from the issue date, by transfer to the account on file. Late amounts carry interest at 1.5 percent a month.",
      notes,
    },
    parties: {
      issuer: { id: "issuer-0", ...issuer },
      customer: { id: "customer-0", ...customer },
    },
  };
}

/** A short invoice, sized to fit inside one page of content. */
export const shortInvoiceData: InvoiceData = build(
  SHORT_ITEMS,
  "INV-2026-0431",
  "Quote the invoice number on the transfer so the payment can be matched."
);

/** A long invoice, sized to run its table past more than one page break. */
export const overflowInvoiceData: InvoiceData = build(
  OVERFLOW_ITEMS,
  "INV-2026-0432",
  "Covers the August and September delivery windows on one invoice, as agreed. Quote the invoice number on the transfer so the payment can be matched, and send queries to the billing address above rather than to the delivery team."
);

/** @jsxRuntime classic */
import React from "react";
import type { Form } from "@paradoc/types";

import { Document } from "@/components/paradoc/document";
import {
  markDocumentRoot,
  scaleTextClasses,
  useDocumentTokens,
  type DocumentData,
  type DocumentTokensInput,
  type FormatOptions,
} from "@paradoc/react";
import { Field } from "@/components/paradoc/field";
import { KeepTogether } from "@/components/paradoc/keep-together";
import { Section } from "@/components/paradoc/section";
import { Table } from "@/components/paradoc/table";
import { Totals } from "@/components/paradoc/totals";
import { invoiceForm, invoiceTokens } from "../../artifacts/paradoc/invoice.artifact";

/**
 * The invoice, composed from the components.
 *
 * One tree, built only from `Document`, `Section`, `Field`, `Table` and
 * `Totals`, that carries no copy of any label, format, or total. It is the same
 * tree the preview paginates and the PDF renders.
 *
 * **There is no `Signature`.** An invoice is a demand for payment rather than
 * an agreement, so the artifact declares no signature slot and the composition
 * draws no signing block. What the document ends on is the terms.
 *
 * **The branding is a token set, not markup.** The accent reaches the section
 * headings and the emphasised total through `Document`; the mark is read from
 * the same tokens rather than from a prop, so a tenant who passes their own set
 * replaces both at once. Bytes resolve to a `data:` URI, so neither the browser
 * nor the engine fetches anything and the composition needs no image wiring.
 *
 * Like the purchase order, this composition does not wrap itself in a `Bundle`:
 * it renders bare so a caller who puts it inside a packet supplies the bundle.
 */

/** Rendered size of the issuer's mark, in CSS pixels. The engine needs both stated. */
const MARK_SIZE_PX = 40;

/**
 * The masthead's organization mark.
 *
 * It is a component of its own so it can read the document's tokens: a hook
 * called in `InvoiceDocument`'s own body would sit above the `Document` that
 * supplies them and would see the package's defaults instead. A tenant who
 * passes no `logo` gets a masthead with no mark rather than someone else's.
 */
function IssuerMark() {
  const { logo } = useDocumentTokens();
  if (logo === undefined) return null;

  return (
    // Decorative: the issuer is named beside it. The mark sits in the row
    // rather than above it so it costs the page no height.
    <KeepTogether
      as="img"
      keepId="logo"
      src={logo}
      alt=""
      width={MARK_SIZE_PX}
      height={MARK_SIZE_PX}
      className="h-10 w-10"
    />
  );
}

export interface InvoiceDocumentProps {
  /** The invoice data to render. */
  data: DocumentData;
  /** Overrides the artifact, for tests that vary it. */
  artifact?: Form;
  /** How values the serializer registry does not cover are formatted, and which registry (US or EU) covers the rest. */
  format?: FormatOptions;
  /** Tenant branding. Defaults to the issuer's own accent and mark. */
  tokens?: DocumentTokensInput;
  /** Application-owned classes applied to the document root. */
  className?: string;
}

/**
 * The composition's content, below the `Document` that supplies its tokens: a
 * hook called in `InvoiceDocument`'s own body would see the package's defaults.
 * Every size and leading here is routed through the token, so the whole
 * document follows `typography` rather than the components alone.
 */
function InvoiceBody({ artifact }: { artifact: Form }) {
  const { typography } = useDocumentTokens();
  const type = (classes: string) => scaleTextClasses(classes, typography.scale);
  return (
    <>

      <Section id="masthead" className="flex flex-row justify-between gap-8 border-b border-neutral-800 pb-4">
        <div className="flex basis-1/2 flex-row gap-3">
          <IssuerMark />
          <div className="flex flex-col gap-1">
            <KeepTogether as="span" keepId="title" className={type("text-lg font-semibold text-neutral-900")}>
              {artifact.title}
            </KeepTogether>
            <Field path="issuer" label={false} className={type("text-sm text-neutral-700")} />
            <Field path="issuerEmail" label={false} className={type("text-sm text-neutral-600")} />
          </div>
        </div>
        <div className="flex basis-1/3 flex-col gap-2">
          <Field path="invoiceNumber" />
          <Field path="issuedOn" />
          <Field path="dueOn" />
          <Field path="currency" />
        </div>
      </Section>

      <Section id="parties" title="Addresses">
        <div className="flex flex-row gap-10">
          <div className="flex basis-1/2 flex-col gap-2">
            <Field path="issuerAddress" label="From" className={type("flex flex-col gap-0.5 text-sm text-neutral-600")} />
            <Field path="purchaseOrderNumber" className={type("flex flex-col gap-0.5 text-sm text-neutral-600")} />
          </div>
          <div className="flex basis-1/2 flex-col gap-1">
            <Field path="customer" className={type("flex flex-col gap-0.5 text-sm font-medium text-neutral-900")} />
            <Field path="customerContact" label={false} className={type("text-sm text-neutral-700")} />
            <Field path="customerAddress" label={false} className={type("text-sm text-neutral-600")} />
          </div>
        </div>
      </Section>

      <Section id="line-items" title="Billed items" className="flex flex-col gap-3">
        <Table
          path="lineItems"
          id="line-items"
          columns={[
            { field: "description", width: "basis-1/2" },
            { field: "quantity", header: "Qty", width: "basis-1/12", align: "right" },
            { field: "unit", width: "basis-1/12" },
            { field: "unitPrice", header: "Unit price", width: "basis-1/6", align: "right" },
            { field: "amount", width: "basis-1/6", align: "right" },
          ]}
        />
        <Totals
          rows={[
            { def: "subtotal" },
            { def: "tax", ratePath: "taxRatePercent" },
            { def: "total", emphasis: true },
          ]}
        />
      </Section>

      <Section id="terms" title="Payment" className="flex flex-col gap-2">
        <Field path="paymentTerms" label={false} className={type("text-sm leading-relaxed text-neutral-800")} />
        <Field path="notes" label={false} className={type("text-sm leading-relaxed text-neutral-600")} />
      </Section>
    </>
  );
}

/**
 * The composed invoice.
 *
 * Exported by name and as the module's default. The default is what a React
 * layer binds to when the renderer imports the module the layer's path names,
 * which is the convention a composition module follows.
 */
export function InvoiceDocument({
  data,
  artifact = invoiceForm,
  format,
  tokens = invoiceTokens,
  className,
}: InvoiceDocumentProps) {
  return (
    <Document artifact={artifact} data={data} format={format} tokens={tokens} id="invoice" className={className}>
      <InvoiceBody artifact={artifact} />
    </Document>
  );
}

markDocumentRoot(InvoiceDocument);
export default InvoiceDocument;
